WITH lines AS (SELECT src.id, src.customer_id, pos, line.product_id, line.qty, line.price, line.promo FROM carts src LATERAL VIEW POSEXPLODE(src.items) e AS pos, line) SELECT promo, customer_id, SORT_ARRAY(COLLECT_SET(promo)) AS promo_list, APPROX_PERCENTILE(price, ARRAY(0.25, 0.5, 0.75)) AS price_quartiles, SUM(qty) FILTER (WHERE promo = 'BUNDLE') AS bundle_total_qty FROM lines GROUP BY ROLLUP (promo, customer_id) ORDER BY promo DESC
